var findLength = function(nums1, nums2) {
    const n = nums1.length, m = nums2.length;
    const dp = new Array(m + 1).fill(0);
    let res = 0;
    for (let i = 1; i <= n; i++) {
        for (let j = m; j >= 1; j--) {
            if (nums1[i - 1] === nums2[j - 1]) {
                dp[j] = dp[j - 1] + 1;
                res = Math.max(res, dp[j]);
            } else {
                dp[j] = 0;
            }
        }
    }
    return res;
};
